code.cpp:
class Solution {
public:
    vector<int> getSubarrayBeauty(vector<int>& nums, int k, int x) {
        int n = nums.size();
        int freq[51] = {0}; // freq[v] = count of value -v in current window
        vector<int> ans;
        ans.reserve(n - k + 1);
        int negCount = 0;

        for (int i = 0; i < n; i++) {
            if (nums[i] < 0) {
                freq[-nums[i]]++;
                negCount++;
            }
            if (i >= k) {
                int old = nums[i - k];
                if (old < 0) {
                    freq[-old]--;
                    negCount--;
                }
            }
            if (i >= k - 1) {
                if (negCount < x) {
                    ans.push_back(0);
                } else {
                    int cnt = 0;
                    for (int v = 50; v >= 1; v--) {
                        cnt += freq[v];
                        if (cnt >= x) {
                            ans.push_back(-v);
                            break;
                        }
                    }
                }
            }
        }
        return ans;
    }
};
